#include <multiset>
#include <algorithm>
#include <iostream>

int main() {
    std::multiset<int> coll = {1, 5, 5, 10};

    // Efficient O(log N) search using member function
    auto pos = coll.find(5);

    if (pos != coll.end()) {
        // Remove only the first instance found
        coll.erase(pos);
    }

    // Avoid this: O(N) search using generic algorithm
    // auto slow_pos = std::find(coll.begin(), coll.end(), 10);
}
